package com.twelvemonkeys.imageio.plugins.bmp;

import org.junit.jupiter.api.Test;

import javax.imageio.IIOException;
import javax.imageio.ImageReadParam;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class BMPImageReaderReadTests {
    @Test
    void readsBottomUp24BitBitmapInDisplayOrder() throws Exception {
        byte[] bmp = bitmap24(
                new int[][]{
                        {0x0000FF, 0xFFFFFF},
                        {0xFF0000, 0x00FF00}
                }
        );

        BMPImageReader reader = new BMPImageReader();
        try (MemoryCacheImageInputStream input =
                     new MemoryCacheImageInputStream(new ByteArrayInputStream(bmp))) {
            reader.setInput(input);

            BufferedImage image = reader.read(0, null);

            assertEquals(2, image.getWidth());
            assertEquals(2, image.getHeight());
            assertEquals(0xFF0000FF, image.getRGB(0, 0));
            assertEquals(0xFFFFFFFF, image.getRGB(1, 0));
            assertEquals(0xFFFF0000, image.getRGB(0, 1));
            assertEquals(0xFF00FF00, image.getRGB(1, 1));
        } finally {
            reader.dispose();
        }
    }

    @Test
    void rejectsImageIndexOutsideAvailableImages() throws Exception {
        byte[] bmp = bitmap24(new int[][]{{0x336699}});

        BMPImageReader reader = new BMPImageReader();
        try (MemoryCacheImageInputStream input =
                     new MemoryCacheImageInputStream(new ByteArrayInputStream(bmp))) {
            reader.setInput(input);

            assertThrows(IndexOutOfBoundsException.class, () -> reader.read(1, null));
        } finally {
            reader.dispose();
        }
    }

    @Test
    void rejectsUnsupportedCompression() throws Exception {
        byte[] bmp = bitmap24(new int[][]{{0x336699}});
        ByteBuffer.wrap(bmp).order(ByteOrder.LITTLE_ENDIAN).putInt(30, 99);

        BMPImageReader reader = new BMPImageReader();
        try (MemoryCacheImageInputStream input =
                     new MemoryCacheImageInputStream(new ByteArrayInputStream(bmp))) {
            reader.setInput(input);

            assertThrows(IIOException.class, () -> reader.read(0, new ImageReadParam()));
        } finally {
            reader.dispose();
        }
    }

    private static byte[] bitmap24(int[][] rowsTopToBottom) {
        int height = rowsTopToBottom.length;
        int width = rowsTopToBottom[0].length;
        int rowSize = ((width * 3 + 3) / 4) * 4;
        int pixelOffset = 54;
        ByteBuffer buffer = ByteBuffer.allocate(pixelOffset + rowSize * height)
                .order(ByteOrder.LITTLE_ENDIAN);

        buffer.put((byte) 'B').put((byte) 'M');
        buffer.putInt(pixelOffset + rowSize * height);
        buffer.putShort((short) 0).putShort((short) 0);
        buffer.putInt(pixelOffset);

        buffer.putInt(40);
        buffer.putInt(width);
        buffer.putInt(height);
        buffer.putShort((short) 1);
        buffer.putShort((short) 24);
        buffer.putInt(0);
        buffer.putInt(rowSize * height);
        buffer.putInt(2835).putInt(2835);
        buffer.putInt(0).putInt(0);

        for (int y = height - 1; y >= 0; y--) {
            int rowStart = buffer.position();

            for (int x = 0; x < width; x++) {
                int rgb = rowsTopToBottom[y][x];
                buffer.put((byte) (rgb & 0xFF));
                buffer.put((byte) ((rgb >>> 8) & 0xFF));
                buffer.put((byte) ((rgb >>> 16) & 0xFF));
            }

            while (buffer.position() - rowStart < rowSize) {
                buffer.put((byte) 0);
            }
        }

        return buffer.array();
    }
}

