package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageReadParam;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertEquals;

class PCXImageReaderReadTests {
    @Test
    void reads24BitImageWithHorizontalSubsampling() throws IOException {
        byte[] pcx = create24BitPcx();

        PCXImageReader reader = new PCXImageReader(new PCXImageReaderSpi());
        try (ImageInputStream input = javax.imageio.ImageIO.createImageInputStream(new ByteArrayInputStream(pcx))) {
            reader.setInput(input);

            ImageReadParam param = reader.getDefaultReadParam();
            param.setSourceSubsampling(2, 1, 0, 0);

            BufferedImage image = reader.read(0, param);

            assertEquals(2, image.getWidth());
            assertEquals(2, image.getHeight());
            assertEquals(0xFF0A0000, image.getRGB(0, 0));
            assertEquals(0xFF1E0000, image.getRGB(1, 0));
            assertEquals(0xFF320000, image.getRGB(0, 1));
            assertEquals(0xFF460000, image.getRGB(1, 1));
        }
        finally {
            reader.dispose();
        }
    }

    private static byte[] create24BitPcx() throws IOException {
        byte[] header = new byte[128];

        header[0] = 0x0A;
        header[1] = 5;
        header[2] = 1;
        header[3] = 8;

        writeUnsignedShortLE(header, 4, 0);
        writeUnsignedShortLE(header, 6, 0);
        writeUnsignedShortLE(header, 8, 3);
        writeUnsignedShortLE(header, 10, 1);

        writeUnsignedShortLE(header, 12, 4);
        writeUnsignedShortLE(header, 14, 2);

        header[65] = 3;
        writeUnsignedShortLE(header, 66, 4);
        writeUnsignedShortLE(header, 68, 1);

        ByteArrayOutputStream imageData = new ByteArrayOutputStream();

        appendPlane(imageData, new int[] {10, 20, 30, 40});
        appendPlane(imageData, new int[] {0, 0, 0, 0});
        appendPlane(imageData, new int[] {0, 0, 0, 0});

        appendPlane(imageData, new int[] {50, 60, 70, 80});
        appendPlane(imageData, new int[] {0, 0, 0, 0});
        appendPlane(imageData, new int[] {0, 0, 0, 0});

        ByteArrayOutputStream pcx = new ByteArrayOutputStream();
        pcx.write(header);
        pcx.write(imageData.toByteArray());
        return pcx.toByteArray();
    }

    private static void appendPlane(ByteArrayOutputStream output, int[] values) {
        Arrays.stream(values).forEach(output::write);
    }

    private static void writeUnsignedShortLE(byte[] bytes, int offset, int value) {
        bytes[offset] = (byte) value;
        bytes[offset + 1] = (byte) (value >>> 8);
    }
}

