public class PCXImageReaderReadTests {

    @Test
    public void readOnEmptyInputThrowsIOException() throws Exception {
        PCXImageReaderSpi spi = new PCXImageReaderSpi();
        PCXImageReader reader = new PCXImageReader(spi);

        try (ImageInputStream iis = ImageIO.createImageInputStream(new ByteArrayInputStream(new byte[0]))) {
            reader.setInput(iis);

            // The read method relies on a PCX header and data; with an empty stream, an IOException
            // is the expected outcome, signaling that no image data could be read.
            assertThrows(IOException.class, () -> reader.read(0, null));
        }
    }
}

