package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.ImageInputStream;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

class VP8FrameDecodeTests {
    @Test
    void decodeReturnsFalseAndStopsImmediatelyForInterFrame() throws IOException {
        try (ImageInputStream stream = new MemoryCacheImageInputStream(
                new ByteArrayInputStream(new byte[]{0x01}))) {
            VP8Frame frame = new VP8Frame(stream, false);
            BufferedImage target = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);

            assertFalse(frame.decode(target.getRaster(), null));
            assertEquals(1L, stream.getStreamPosition());
        }
    }
}

package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import javax.imageio.stream.ImageInputStream;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.awt.image.BufferedImage;
import java.awt.image.WritableRaster;

import static org.junit.jupiter.api.Assertions.*;

public class VP8FrameDecodeTests {

    @Test
    public void decodeReturnsFalseForNonIntraFrame() throws IOException {
        // Prepare a minimal VP8Frame bitstream where frameType (bit 0 of first byte) != 0
        // Setting first byte to 0x01 makes frameType == 1 (non-intra)
        byte[] data = new byte[] { 0x01 };

        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));

        VP8Frame frame = new VP8Frame(stream, false);

        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
        WritableRaster raster = img.getRaster();

        boolean result = frame.decode(raster, null);

        assertFalse(result, "decode should return false when the frame is not an intra frame (frameType != 0)");
    }
}
